    "中继在双方直连失败时兜底转发流量，已默认开启并预填官方公共节点；可按需关闭或改为自建中继。": "リレーは直接接続に失敗した場合のフォールバックとしてトラフィックを転送します。既定で有効で、公式の公開ノードが事前入力されています。必要に応じて無効化したり、独自のリレーに変更したりできます。",
