    "导出本机设置后，把文本复制到另一台设备即可导入合并；实时同步需多端共用存储，暂未开放。": "ローカル設定をエクスポートした後、テキストを別の端末にコピーすればインポートしてマージできます。リアルタイム同期には複数端末でのストレージ共有が必要で、まだ利用できません。",
    "将删除与「{0}」的本机聊天记录，且无法恢复。": "「{0}」とのローカルチャット履歴を削除します。元に戻せません。",
    "将尽力删除群盘中的离线密文对象并停止群盘同步；群消息仍可在线收发，但成员离线期间无法从群盘补齐。此操作不可恢复。": "グループドライブ内のオフライン暗号対象をできる限り削除し、同期を停止します。グループメッセージはオンラインで送受信できますが、オフライン中のメンバーはグループドライブから補完できません。この操作は元に戻せません。",
