    "开启后入库成功即删除 S3 密文对象；仅在单设备独占桶时使用，多端共用同一桶请保持关闭（由桶生命周期清理）": "有効にすると、保存が成功した時点で S3 の暗号オブジェクトを削除します。単一の端末がバケットを占有する場合のみ使用してください。複数端末で同じバケットを共有する場合は無効のままにしてください（バケットのライフサイクルで削除します）。",
