  'ar': <String, String>{    '启用自动归属地': 'تفعيل تحديد المنطقة تلقائيًا',
    '开启前必须设置密码；关闭只断开密码静默远控，聊天里发起的远控不受影响': 'عيّن كلمة مرور قبل التفعيل. الإيقاف ينهي التحكم الصامت المعتمد على كلمة المرور فقط؛ ولا يؤثر على التحكم عن بُعد الذي يبدأ في المحادثة.',

    '远程控制中': 'جارٍ التحكم عن بُعد',
