    '点击打开远程控制授权界面': 'اضغط لفتح شاشة موافقة التحكم عن بُعد',
    '点击管理远程控制': 'اضغط لإدارة التحكم عن بُعد',

    '程序已内置离线 IP 库，启用后依据 P2P 连接中的 IP 在本机推断省市与地图中心点。不会上传你的 IP 或位置，也不会把归属地发送给对端；已手动填写的地区和坐标不会被覆盖。': 'قاعدة IP دون اتصال مضمّنة في التطبيق. عند التفعيل، يتم استنتاج المحافظة/المدينة ومركز الخريطة محليًا من IP الظاهر في اتصال P2P. لا يتم رفع IP أو الموقع ولا إرسال المنطقة إلى الطرف الآخر؛ تُحفظ المنطقة والإحداثيات التي أدخلتها يدويًا.',
    '同意并启用': 'موافقة وتفعيل',
    '本机离线推断，默认关闭；不会上传 IP 或位置': 'استنتاج محلي على الجهاز، معطل افتراضيًا؛ لا يتم رفع IP أو الموقع',
    '自动归属地': 'تحديد المنطقة تلقائيًا',
