    '通知说明': 'حول الإشعارات',
    '开启后，离线消息会唤醒设备并在通知栏显示；通知只包含「有新消息」提示，不携带正文、发送者或会话内容，收到后由设备自行拉取密文。桌面端没有系统通知通道，请保持应用开启。': 'عند التفعيل، توقظ الرسائل غير المتصلة الجهاز وتظهر في شريط الإشعارات. يحتوي الإشعار على نص "رسالة جديدة" فقط، دون محتوى أو مرسل أو تفاصيل المحادثة؛ يجلب الجهاز النص المشفر لاحقًا. لا توجد قناة إشعارات نظام على سطح المكتب، فأبقِ التطبيق مفتوحًا.',
    'Android / iOS 需要在宿主工程中配置 FCM / APNs 凭证；Web 端浏览器通知无需凭证，后台唤醒需部署者提供 VAPID 公钥。': 'يتطلب Android / iOS بيانات اعتماد FCM / APNs في تطبيق المضيف. إشعارات المتصفح على الويب لا تتطلب بيانات اعتماد، بينما يتطلب الإيقاظ في الخلفية مفتاح VAPID عامًا من الناشر.',
