  'he': <String, String>{    '启用自动归属地': 'הפעלת זיהוי אזור אוטומטי',
    '开启前必须设置密码；关闭只断开密码静默远控，聊天里发起的远控不受影响': 'הגדירו סיסמה לפני ההפעלה. כיבוי מסיים רק שלט מרחוק שקט המבוסס על סיסמה; בקשות שנפתחו בצ\'אט אינן מושפעות.',

