    '程序已内置离线 IP 库，启用后依据 P2P 连接中的 IP 在本机推断省市与地图中心点。不会上传你的 IP 或位置，也不会把归属地发送给对端；已手动填写的地区和坐标不会被覆盖。': 'מסד נתוני IP מקומי מובנה באפליקציה. בהפעלה, המחוז/העיר ומרכז המפה מסיקים מקומית מה-IP הנראה בחיבור P2P. ה-IP או המיקום אינם מועלים ולא נשלחים לצד השני; אזור וקואורדינטות שהזנת ידנית לא נדרסים.',
    '同意并启用': 'מסכים ומפעיל',
