    '通知说明': 'על התראות',
    '开启后，离线消息会唤醒设备并在通知栏显示；通知只包含「有新消息」提示，不携带正文、发送者或会话内容，收到后由设备自行拉取密文。桌面端没有系统通知通道，请保持应用开启。': 'כשהאפשרות מופעלת, הודעות לא מקוונות מעירות את המכשיר ומופיעות בסרגל ההתראות. ההתראה מכילה רק "הודעה חדשה" וללא תוכן, שולח או פרטי שיחה; המכשיר שולף את הטקסט המוצפן afterwards. בשולחן העבודה אין ערוץ התראות מערכת, לכן השאר את האפליקציה פתוחה.',
    'Android / iOS 需要在宿主工程中配置 FCM / APNs 凭证；Web 端浏览器通知无需凭证，后台唤醒需部署者提供 VAPID 公钥。': 'ב-Android / iOS נדרשים אישורי FCM / APNs בפרויקט המארח. התראות דפדפן באינטרנט אינן דורשות אישורים; הערה ברקע דורשת מפתח VAPID ציבורי מהמפרסם.',
